W = 5
P = "Verbeterproject"
PR = "Presentatie"

# ---------- MC: borging en eigenaarschap ----------
mc("pp5-m01", W, P, "Wat betekent 'borgen' volgens de les van week 5?",
   ["De verbetering loskoppelen van de aanwezigheid van het studentteam, zodat ze blijft werken",
    "De verbetering zo snel mogelijk organisatiebreed invoeren na een geslaagde pilot",
    "De verbetering opnemen in het adviesrapport met een duidelijke onderbouwing",
    "De verbetering laten goedkeuren door de opdrachtgever voordat de pilot start"], 0,
   "Zonder bewuste borging zakt een organisatie vrijwel altijd terug in oude gewoonten. Een geslaagde pilot is het begin, niet het eindpunt.")
mc("pp5-m02", W, P, "Welke bouwsteen van het borgingsplan borgt niet het proces, maar de kennis?",
   ["Standaardisatie", "KPI-opvolging", "Overdracht", "Lessons learned"], 3,
   "Lessons learned leggen vast wat goed ging, wat stroef liep en welke aannames niet klopten. Dat is waardevol voor de opdrachtgever, een volgend team en je eigen transfer naar stage.")
mc("pp5-m03", W, P, "Wat is het doel van visueel management bij standaardisatie?",
   ["Het proces mooier presenteren aan de opdrachtgever",
    "Zichtbaar maken of er volgens de standaard gewerkt wordt",
    "De SOP vervangen door pictogrammen",
    "Bijhouden hoeveel tijd elke medewerker aan een taak besteedt"], 1,
   "Visueel management maakt afwijkingen van de standaard direct zichtbaar. FM-voorbeeld: een SOP voor het melden van storingen die zichtbaar bij de servicedesk hangt.")
mc("pp5-m04", W, P, "Met welke S uit 5S hangt borging het sterkst samen?",
   ["Scheiden", "Schikken", "Schoonmaken", "Standhouden"], 3,
   "De vijfde S, Standhouden (Sustain), vraagt de discipline om de afspraak dag in dag uit te blijven volgen.")
mc("pp5-m05", W, P, "In de Control-fase meet je vaak dezelfde KPI's als in de Measure-fase. Wat is het verschil?",
   ["In Control meet je alleen nog de klanttevredenheid en niet meer het proces",
        "In Measure toon je het probleem aan, in Control zie je vroeg dat het afdrijft",
        "In Control meet de docent de KPI's, in Measure doet het studentteam dat",
        "Er is geen verschil, in Control herhaal je simpelweg de nulmeting"], 1,
   "Dezelfde KPI's, ander doel: niet het probleem aantonen, maar vroeg zien dat het proces 'out of control' raakt.")
mc("pp5-m06", W, P, "Een team schrijft in het borgingsplan: 'KPI: doorlooptijd van meldingen, norm maximaal 4 dagen.' Wat ontbreekt nog volgens de eerste stap van KPI-sturing?",
   ["Een ingrijpgrens", "Een PUGH-matrix", "Een RPN-score", "Een tweede sponsor"], 0,
   "Stap 1 is de norm én de grens waarbij je ingrijpt bepalen. Daarna volgen een vast ritme en ingrijpen bij afwijking.")
mc("pp5-m07", W, P, "'Een KPI die niemand bekijkt, borgt niets.' Welke stap van KPI-sturing voorkomt dit vooral?",
   ["Een norm en een ingrijpgrens bepalen",
        "Een vast ritme waarop iemand de cijfers bekijkt",
        "De KPI opnemen in de SOP bij de balie",
        "De KPI maandelijks naar de opdrachtgever mailen"], 1,
   "KPI-sturing: (1) norm en ingrijpgrens, (2) een vast ritme, wekelijks of maandelijks, (3) ingrijpen bij afwijking.")
mc("pp5-m08", W, P, "Hoe noemt de docent een verbetering zonder eigenaar?",
   ["Een quick win", "Een wees", "Een los eindje", "Een pilot"], 1,
   "Zonder eigenaar is een verbetering 'een wees', door niemand bewaakt. Daarom krijgt elke verbetering een naam: proceseigenaar, teamleider of coördinator.")
mc("pp5-m09", W, P, "Aan welke Lean-waarde koppelt de les het eigenaarschap?",
   ["Respect voor mensen", "Just-in-time", "Jidoka", "Flow"], 0,
   "Betrek medewerkers, neem hun zorgen serieus en vier successen. Hún verbetering overleeft jullie vertrek.")
mc("pp5-m10", W, P, "Bij een evaluatiemoment blijkt dat het proces onvoldoende presteert. Wat gebeurt er dan in de Act-stap?",
   ["De standaard wordt bijgewerkt en vastgezet", "Er start een nieuwe verbeterronde", "De KPI wordt geschrapt", "Het project wordt overgedragen"], 1,
   "Presteert het goed, dan werk je de standaard bij. Presteert het onvoldoende, dan start een nieuwe verbeterronde.")
mc("pp5-m11", W, P, "Wat is Kaizen?",
   ["Een grote eenmalige reorganisatie", "Kleine, dagelijkse verbeteringen", "Een methode om fouten te scoren", "Een formele projectafsluiting"], 1,
   "PDCA (van Deming) is de motor van continu verbeteren, in Lean Kaizen: kleine dagelijkse verbeteringen.")
mc("pp5-m12", W, P, "Waarom moeten evaluatiemomenten volgens de les gekoppeld zijn aan de KPI's én de eigenaar?",
   ["Anders zakt het evaluatiemoment weg",
    "Omdat de opdrachtgever dat verplicht stelt",
    "Omdat de KPI's anders niet SMART zijn",
    "Zodat de docent de evaluatie kan beoordelen"], 0,
   "Een evaluatiemoment dat niet vast staat, niet over de KPI's gaat en niemand als eigenaar heeft, verdwijnt uit de agenda.")
mc("pp5-m13", W, P, "Wat betekent 'actief overdragen' van het overdrachtsdossier?",
   ["Het dossier op tijd mailen naar de opdrachtgever",
    "Toelichten, vragen beantwoorden en checken of de eigenaar ermee uit de voeten kan",
    "Het dossier laten ondertekenen door de docent",
    "Het dossier op het intranet zetten zodat iedereen het kan lezen"], 1,
   "Niet alleen aanleveren, maar toelichten en checken. Zo wordt jullie werk onafhankelijk van jullie zelf.")
mc("pp5-m14", W, P, "In het praktijkvoorbeeld van de zorginstelling (vijf meldkanalen) borgde het team de verbetering met twee KPI's. Welke combinatie was dat?",
   ["Klanttevredenheid van bewoners en het aantal meldingen per maand",
        "Doorlooptijd maximaal 4 dagen en minstens 90% via het centrale meldpunt",
        "Doorlooptijd maximaal 11 dagen en minder dan vijf meldkanalen in gebruik",
        "Aantal gele briefjes per week en aantal telefoontjes naar de servicedesk"], 1,
   "De doorlooptijd daalde in de pilot van 11 naar 3 dagen. Met de twee KPI's bewaakt de teamleider Facilitair dat het zo blijft.")
mc("pp5-m15", W, P, "Een team vult bij eigenaarschap in: 'iemand van de facilitaire afdeling'. Welke vraag stelt de docent dan volgens de notities?",
   ["Hoeveel uur per week kan die persoon hieraan besteden?",
    "Is het een echte naam of rol, en weet die persoon het eigenlijk al?",
    "Heeft die persoon een Lean-certificaat?",
    "Staat die persoon in het organogram boven de opdrachtgever?"], 1,
   "Teams haken vooral af bij de KPI-normen en het eigenaarschap. Vaak blijkt de beoogde eigenaar van niets te weten.")

# ---------- MC: training 3 ----------
mc("pp5-m16", W, PR, "Bij welke fase van je project hoort het PROA-blok Oorzaak?",
   ["Define", "Measure", "Analyze", "Control"], 2,
   "Probleem: Define en Measure. Risico: Measure. Oorzaak: Analyze. Advies: Generate, Improve en Control.")
mc("pp5-m17", W, PR, "Welke tip over visualiseren geeft de training?",
   ["Gebruik visuals om het denken te ontlasten, niet om te versieren",
    "Zet op elke slide minstens twee afbeeldingen",
    "Gebruik zo veel mogelijk kleuren zodat de slides opvallen",
    "Zet de volledige tekst onder elke visual, voor wie het later naleest"], 0,
   "Beperk visuele ruis, één boodschap per slide, en een adviespresentatie is geen rapport.")
mc("pp5-m18", W, PR, "Vanuit wie moet je volgens de training vooral denken bij een adviespresentatie?",
   ["Vanuit de docent die de presentatie beoordeelt",
        "Vanuit de beslisser: wat is nodig om ja te zeggen?",
        "Vanuit de medewerkers die ermee gaan werken",
        "Vanuit je eigen team en wat jullie trots maakt"], 1,
   "Denk vanuit de beslisser: wat heeft die nodig om JA te zeggen, en wat maakt dat de opdrachtgever wil investeren?")

# ---------- open ----------
op("pp5-o1", W, P, "Waarom is borging nodig, ook na een geslaagde pilot? Noem de kernvraag van de Control-fase en geef een FM-voorbeeld van wat er zonder borging gebeurt.",
   "Zonder bewuste borging zakt een organisatie vrijwel altijd terug in oude gewoonten; de winst verdampt en na een paar maanden is het alsof er nooit een project was. Een geslaagde pilot is het begin, niet het eindpunt. Kernvraag: 'Wat moet blijven bestaan als het studentteam weg is?' Voorbeeld: een nieuw schoonmaakschema werkt zolang de student meekijkt, maar verwatert zodra die weg is; of een centraal meldpunt waarna de afdeling binnen enkele maanden terug is bij de gele briefjes.",
   ["Terugval in oude gewoonten uitgelegd", "Kernvraag van Control juist", "Passend FM-voorbeeld"])
op("pp5-o2", W, P, "Werk de drie stappen van KPI-sturing uit voor de KPI 'percentage vergaderzalen dat op tijd gereed staat'.",
   "Stap 1, norm en ingrijpgrens: bijvoorbeeld norm 95% op tijd gereed, ingrijpen als het onder 90% zakt. Stap 2, vast ritme: de facilitair coördinator bekijkt het percentage elke week in het teamoverleg (of maandelijks). Stap 3, ingrijpen bij afwijking: bij minder dan 90% zoekt de coördinator met het zaalteam naar de oorzaak en past de checklist of planning aan, eventueel een nieuwe PDCA-ronde.",
   ["Norm én ingrijpgrens met getallen", "Vast ritme met wie het bekijkt", "Concrete actie bij afwijking"])
op("pp5-o3", W, P, "Leg uit hoe de PDCA-cyclus een verbetering levend houdt na de pilot. Welke twee stappen zijn bij borging het belangrijkst en wat gebeurt er in die stappen?",
   "PDCA (Deming) is de motor van continu verbeteren (Kaizen). Bij borging draait het vooral om Check en Act. Check: met gegevens meten of het proces nog presteert zoals afgesproken; hier grijpt de KPI-opvolging op aan. Act: presteert het goed, dan werk je de standaard bij; presteert het onvoldoende, dan start een nieuwe verbeterronde. Evaluatiemomenten moeten vast ingepland zijn en gekoppeld aan KPI's en eigenaar, bijvoorbeeld maandelijks in het teamoverleg.",
   ["Check juist uitgelegd met koppeling aan KPI's", "Act juist: standaard bijwerken of nieuwe ronde", "Vaste evaluatiemomenten of Kaizen genoemd"])
op("pp5-o4", W, P, "Wat is het verschil tussen de bouwstenen overdracht en lessons learned? Leg bij overdracht uit wat 'actief' overdragen betekent.",
   "Overdracht maakt de verbetering overdraagbaar: je bundelt SOP's, KPI-definities, eigenaarschap en evaluatie-afspraken in één overdrachtsdossier. Actief betekent: niet alleen aanleveren, maar toelichten, vragen beantwoorden en checken of de eigenaar ermee uit de voeten kan. Lessons learned borgen niet het proces maar de kennis: wat ging goed, wat liep stroef, welke aannames klopten niet, wat zou een volgend team anders doen.",
   ["Overdracht: dossier met de juiste inhoud", "Actief overdragen juist uitgelegd", "Lessons learned borgen kennis, niet het proces"])
op("pp5-o5", W, P, "Hoe leg je een nieuwe werkwijze vast zodat ze blijft? Gebruik de begrippen SOP, mura, 5S en visueel management.",
   "Zonder vastgelegde werkwijze ontstaat variatie, in Lean mura, een vorm van verspilling. Daarom leg je standaardwerk vast in een SOP met afbakening, KPI's en voorschriften, volgorde van stappen en vastleggen. De vijfde S van 5S, Standhouden, vraagt de discipline om de afspraak elke dag te volgen. Visueel management maakt zichtbaar of er volgens de standaard gewerkt wordt, bijvoorbeeld een SOP die zichtbaar bij de servicedesk hangt.",
   ["Mura juist gekoppeld aan ontbreken van standaard", "SOP met (een deel van) de vier onderdelen", "5S Standhouden en visueel management juist"])
op("pp5-o6", W, PR, "Jullie advies is een centraal meldpunt voor storingen bij een zorginstelling. De doorlooptijd was 11 dagen, meldingen raakten kwijt via vijf kanalen. Zet de kern van je adviespresentatie in de PROA-structuur: wat vertel je per blok?",
   "Probleem: meldingen raken kwijt doordat ze via vijf kanalen binnenkomen (Define en Measure). Risico: de omvang, gemiddeld 11 dagen doorlooptijd, met gevolgen voor bewoners en medewerkers (Measure). Oorzaak: er is geen centraal registratiepunt en geen vaste afhandelvolgorde (Analyze). Advies: één digitaal meldpunt (mogelijkheden en keuze), hoe je het invoert (pilot, training, planning) en hoe je grip houdt (SOP, KPI doorlooptijd maximaal 4 dagen, eigenaar).",
   ["Probleem en Risico juist gescheiden", "Oorzaak passend bij Analyze", "Advies met keuze, implementatie én borging"])

# ---------- casus ----------
cs("pp5-c1", W, P, "Afvalscheiding op de campus van Hogeschool Lingewaard",
   "Hogeschool Lingewaard (fictief) heeft op twee verdiepingen een pilot gedaan met nieuwe afvalstations met duidelijke pictogrammen. De vervuiling van de papierstroom daalde van 30% naar 12%. De opdrachtgever, het hoofd Facilitaire Zaken, wil dat de stations na de zomer in het hele gebouw staan. Het studentteam vertrekt over vier weken.",
   [("Werk vier van de zes bouwstenen van het borgingsplan concreet uit voor deze verbetering.",
     "Standaardisatie: een werkinstructie voor schoonmaak (wat gaat waar, wanneer legen) plus pictogrammen en een bord bij elk station (visueel management). KPI-opvolging: percentage vervuiling van de papierstroom, norm maximaal 12%, ingrijpen boven 15%, maandelijks gemeten. Eigenaarschap: de coördinator schoonmaak of het hoofd Facilitaire Zaken met naam. Evaluatie: maandelijks in het facilitaire overleg de KPI bespreken en de instructie bijstellen (PDCA). Overdracht: dossier met instructie, KPI-definitie en afspraken, mondeling toegelicht. Lessons learned: bijvoorbeeld 'pictogrammen werkten beter dan tekst'.",
     ["Twee bouwstenen concreet en passend", "Nog twee bouwstenen concreet", "KPI met norm en ingrijpgrens"]),
    ("Het hoofd Facilitaire Zaken stelt voor: 'De conciërge let er wel op.' Beoordeel dit voorstel met de les over eigenaarschap.",
     "Onvoldoende: eigenaarschap vraagt een vaste verantwoordelijke met naam of rol die de KPI bewaakt en kan ingrijpen. 'Wel op letten' is geen afspraak. Vragen van de docent: is het een echte naam of rol, en weet die persoon het al? De conciërge heeft mogelijk geen mandaat over schoonmaak. Beter: een proceseigenaar met mandaat die het weet en heeft ingestemd, gekoppeld aan de KPI en de evaluatiemomenten.",
     ["Voorstel kritisch beoordeeld", "Eis: naam of rol, en de persoon weet het", "Koppeling aan mandaat, KPI of evaluatie"]),
    ("Waarom is Kotter stap 8 hier van belang, en wat kan het team in de laatste vier weken doen om die stap te ondersteunen?",
     "Kotter stap 8 is 'borg in de cultuur': pas als afval scheiden 'zo doen wij dat hier' wordt, blijft het bestaan. Dat vraagt dat normen en gedrag meebewegen. In vier weken: medewerkers en schoonmakers betrekken bij de uitrol, hun zorgen serieus nemen (respect voor mensen), de resultaten van de pilot zichtbaar maken en vieren, en de eigenaar nu al de KPI laten bespreken.",
     ["Stap 8 juist uitgelegd", "Minstens twee concrete acties"])])
cs("pp5-c2", W, P, "Een zwakke borgingsparagraaf",
   "Een team levert deze borgingsparagraaf in voor de verbeterde uitgifte van werkplekken: 'Standaardisatie: de nieuwe werkwijze is bekend bij iedereen. KPI: tevredenheid van medewerkers. Eigenaar: het team. Evaluatie: als het nodig is. Overdracht: we mailen het rapport naar de opdrachtgever. Lessons learned: het project ging goed.'",
   [("Benoem per bouwsteen wat er zwak aan is.",
     "Standaardisatie: niets vastgelegd, geen SOP of visueel management; 'bekend bij iedereen' leidt tot variatie (mura). KPI: geen norm, ingrijpgrens of meetritme, en tevredenheid alleen is vaag. Eigenaar: 'het team' is niemand; er hoort een naam of rol bij. Evaluatie: 'als het nodig is' is geen vast moment, dus het zakt weg. Overdracht: mailen is niet actief overdragen. Lessons learned: een dooddoener, geen concrete les.",
     ["Drie bouwstenen juist bekritiseerd", "Alle zes bouwstenen juist bekritiseerd"]),
    ("Herschrijf de bouwstenen KPI, eigenaar en evaluatie zodat ze voldoen.",
     "KPI: percentage medewerkers dat binnen 5 minuten een werkplek heeft, norm 95%, ingrijpen onder 90%, wekelijks gemeten via het reserveringssysteem. Eigenaar: de facilitair coördinator (naam), die heeft ingestemd en het mandaat heeft om de werkwijze aan te passen. Evaluatie: elke eerste maandag van de maand bespreekt de coördinator de KPI in het teamoverleg; bij afwijking start een nieuwe PDCA-ronde.",
     ["KPI met norm, grens en ritme", "Eigenaar met naam of rol die het weet", "Vast evaluatiemoment gekoppeld aan KPI en eigenaar"])])
cs("pp5-c3", W, P, "Terugval bij de servicedesk van gemeente Overbetuwe",
   "Bij gemeente Overbetuwe (fictief) voerde een studentteam vorig jaar een digitaal meldformulier in. De pilot was een succes. Vier maanden na hun vertrek komen meldingen weer per telefoon en via briefjes binnen, en niemand weet wie het formulier beheert. Er hangt geen instructie meer bij de balie. De nieuwe teamleider vraagt jullie om advies.",
   [("Welke bouwstenen van het borgingsplan zijn vermoedelijk niet goed ingevuld? Onderbouw met de signalen uit de casus.",
     "Eigenaarschap: niemand weet wie het formulier beheert, dus de verbetering is een wees. Standaardisatie en visueel management: er hangt geen instructie meer, dus variatie sluipt terug. KPI-opvolging: niemand merkte de terugval op, dus er werd niet gemeten of er was geen ingrijpgrens. Evaluatiemomenten: geen vast moment waarop dit besproken werd. Overdracht: kennelijk niet actief overgedragen.",
     ["Eigenaarschap met signaal", "Standaardisatie of visueel management met signaal", "KPI of evaluatie met signaal"]),
    ("Stel een herstelplan op met de PDCA-cyclus.",
     "Plan: wijs de teamleider aan als proceseigenaar, stel de KPI's vast (percentage meldingen via het formulier, norm 90%; doorlooptijd) met ingrijpgrens. Do: hang de SOP weer zichtbaar bij de balie, instrueer de baliemedewerkers. Check: meet maandelijks de KPI's in het teamoverleg. Act: bij goed presteren de standaard bijwerken, bij onvoldoende presteren een nieuwe verbeterronde, bijvoorbeeld met 5x Waarom naar de reden dat mensen weer bellen.",
     ["Plan met eigenaar en KPI", "Do en Check concreet", "Act juist: standaard bijwerken of nieuwe ronde"])])
